def hardware_breakpoint_command(runtime_address: int) -> str:
    if runtime_address <= 0 or runtime_address & 0x3:
        raise ValueError("hardware breakpoint address must be positive and ARM64-aligned")
    return "breakpoint set --hardware --address 0x%x" % runtime_address


def classify_hardware_breakpoint_install(
    command_result, added_breakpoint_ids, resolved_locations, callback_install_return
):
    success_statuses = {
        "eReturnStatusSuccessFinishNoResult",
        "eReturnStatusSuccessFinishResult",
    }
    if (not command_result.get("succeeded")
            or command_result.get("return_status_name") not in success_statuses):
        return "command_failed"
    if len(added_breakpoint_ids) != 1:
        return "breakpoint_identity_unresolved"
    if resolved_locations < 1:
        return "location_unresolved"
    if callback_install_return is False:
        return "callback_install_failed"
    return "installed"


