def command(command_text):
    result = lldb.SBCommandReturnObject()
    status = interpreter.HandleCommand(command_text, result)
    value = int(status)
    return {
        "command": command_text,
        "return_status": value,
        "return_status_name": status_names.get(value, "unknown"),
        "result_status": int(result.GetStatus()),
        "succeeded": bool(result.Succeeded()),
        "output": result.GetOutput() or "",
        "error": result.GetError() or "",
    }

def state(process):
    if not process or not process.IsValid():
        return {"valid": False, "pid": None, "state": None, "state_name": "invalid"}
    value = int(process.GetState())
    return {
        "valid": True,
        "pid": int(process.GetProcessID()),
        "state": value,
        "state_name": state_names.get(value, "unknown"),
    }

def current_breakpoint_ids(target):
    ids = set()
    for index in range(target.GetNumBreakpoints()):
        bp = target.GetBreakpointAtIndex(index)
        if bp and bp.IsValid():
            ids.add(int(bp.GetID()))
    return ids

def resolved_breakpoint_locations(bp, target):
    resolved = []
    for index in range(bp.GetNumLocations()):
        location = bp.GetLocationAtIndex(index)
        if not location or not location.IsValid():
            continue
        address = location.GetAddress()
        if not address or not address.IsValid():
            continue
        load_address = address.GetLoadAddress(target)
        if load_address == lldb.LLDB_INVALID_ADDRESS:
            continue
        is_resolved_method = getattr(location, "IsResolved", None)
        if is_resolved_method is not None and not is_resolved_method():
            continue
        resolved.append(hex(load_address))
    return resolved

def install_hardware_breakpoint(target, site_name, unslid, runtime_address,
                                breakpoints):
    command_text = hardware_breakpoint_command(runtime_address)
    before_ids = current_breakpoint_ids(target)
    report["candidate_sites"][site_name]["breakpoint_command"] = command_text
    emit("hardware_breakpoint_command_before", site=site_name,
         command=command_text, runtime_address=hex(runtime_address))
    command_result = command(command_text)
    after_ids = current_breakpoint_ids(target)
    added_ids = sorted(after_ids - before_ids)
    report["candidate_sites"][site_name]["breakpoint_command_result"] = command_result
    report["candidate_sites"][site_name]["new_breakpoint_ids"] = added_ids

    added_breakpoints = []
    for bp_id in added_ids:
        bp = target.FindBreakpointByID(bp_id)
        if bp and bp.IsValid():
