            _bp_site[bp_id] = site_name
            added_breakpoints.append(bp)

    emit("hardware_breakpoint_command_after", site=site_name,
         return_status=command_result["return_status"],
         return_status_name=command_result["return_status_name"],
         succeeded=command_result["succeeded"],
         output=command_result["output"], error=command_result["error"],
         added_breakpoint_ids=added_ids)

    if (command_result["return_status"] not in finish_statuses
            or not command_result["succeeded"]):
        report["candidate_sites"][site_name]["breakpoint_setup_status"] = "command_failed"
        raise RuntimeError(
            "hardware breakpoint command failed for %s: %s"
            % (site_name, command_result["error"] or command_result["return_status_name"])
        )
    if len(added_breakpoints) != 1:
        report["candidate_sites"][site_name]["breakpoint_setup_status"] = (
            "breakpoint_identity_unresolved"
        )
