    report["candidate_sites"][site_name]["callback_install_status"] = (
        "installed" if callback_ok else "failed"
    )
    emit("callback_install_after", site=site_name, breakpoint_id=bp_id,
         return_value=repr(callback_result), succeeded=callback_ok)
    if not callback_ok:
        report["candidate_sites"][site_name]["breakpoint_setup_status"] = (
            "callback_install_failed"
