def listener_for(process, name):
    listener = lldb.SBListener(name)
    broadcaster = process.GetBroadcaster()
    mask = lldb.SBProcess.eBroadcastBitStateChanged
    registered = int(broadcaster.AddListener(listener, mask))
    if registered & int(mask) == 0:
        raise RuntimeError("could not subscribe to target process state events")
    return listener, broadcaster, mask

def remove_listener(listener, broadcaster, mask):
    try:
        broadcaster.RemoveListener(listener, mask)
    except Exception as error:
        emit("listener_remove_exception", error=str(error))

def wait_state(process, expected, timeout, listener, broadcaster, mask, phase):
    seen = []
    def record(kind, value):
        item = {
            "phase": phase,
            "kind": kind,
            "pid": int(process.GetProcessID()) if process.IsValid() else None,
            "state": int(value),
            "state_name": state_names.get(int(value), "unknown"),
        }
        seen.append(item)
        print('MHFU_RENDER_STATE=' + json.dumps(item, sort_keys=True), flush=True)
    initial = state(process)
    if initial["valid"]:
        record("snapshot", initial["state"])
        if initial["pid"] != EXPECTED_PID:
            return {"reached": False, "reason": "PID mismatch", "state": initial,
                    "transitions": seen}
        if initial["state"] == expected:
            return {"reached": True, "reason": "already in expected state",
                    "state": initial, "transitions": seen}
    elif expected != lldb.eStateDetached:
        return {"reached": False, "reason": "invalid process handle",
                "state": initial, "transitions": seen}

    deadline = time.monotonic() + timeout
    terminal = {lldb.eStateExited, lldb.eStateCrashed, lldb.eStateUnloaded,
                 lldb.eStateInvalid}
    while time.monotonic() < deadline:
        remaining = deadline - time.monotonic()
        event = lldb.SBEvent()
        try:
            received = listener.WaitForEventForBroadcasterWithType(
                max(1, int(math.ceil(remaining))), broadcaster, mask, event
            )
        except Exception as error:
            current = state(process)
            emit("state_wait_exception", phase=phase, state=current, error=str(error))
            return {"reached": False, "reason": "listener wait exception",
                    "state": current, "transitions": seen}
        event_state = None
        if received:
            event_state = int(lldb.SBProcess.GetStateFromEvent(event))
            record("event", event_state)
            event_process = lldb.SBProcess.GetProcessFromEvent(event)
            event_pid = (int(event_process.GetProcessID())
                         if event_process and event_process.IsValid() else None)
            if (not lldb.SBProcess.EventIsProcessEvent(event)
                    or (event_pid is not None and event_pid != EXPECTED_PID)):
                return {"reached": False, "reason": "unexpected process event",
                        "state": state(process), "transitions": seen}
        current = state(process)
        if current["valid"]:
            record("snapshot", current["state"])
            if current["pid"] != EXPECTED_PID:
                return {"reached": False, "reason": "PID changed",
                        "state": current, "transitions": seen}
            if current["state"] == expected:
                return {"reached": True, "reason": "expected state observed",
                        "state": current, "transitions": seen}
            if current["state"] in terminal:
                return {"reached": False, "reason": "terminal state observed",
                        "state": current, "transitions": seen}
        elif (expected == lldb.eStateDetached and received
              and event_state == lldb.eStateDetached):
            return {"reached": True, "reason": "detach event confirmed",
                    "state": {"valid": False, "pid": EXPECTED_PID,
                              "state": lldb.eStateDetached,
                              "state_name": "eStateDetached"},
                    "transitions": seen}
        elif expected != lldb.eStateDetached:
            return {"reached": False, "reason": "process handle became invalid",
                    "state": current, "transitions": seen}
    current = state(process)
    return {"reached": False, "reason": "bounded state wait timed out",
            "timed_out": True, "state": current, "transitions": seen}

def register_value(frame, name):
    try:
        value = frame.FindRegister(name)
        if value and value.IsValid():
            return value.GetValueAsUnsigned()
    except Exception:
        pass
    return None

def main_image_file_address(frame, runtime_address):
    if runtime_address is None:
        return None
    try:
        process = frame.GetThread().GetProcess()
        target = process.GetTarget()
        address = target.ResolveLoadAddress(runtime_address)
        if not address or not address.IsValid():
            return None
        module = address.GetModule()
        if not module or not module.IsValid():
            return None
        spec = module.GetFileSpec()
        uuid = (module.GetUUIDString() or "").replace("-", "").lower()
        if (not spec or spec.GetFilename() != EXECUTABLE_NAME
                or uuid != EXPECTED_UUID):
            return None
        file_address = address.GetFileAddress()
        return None if file_address == lldb.LLDB_INVALID_ADDRESS else file_address
    except Exception:
        return None

def on_render_hit(frame, bp_loc, internal_dict):
    global _total_hits, _callback_errors, _stop_reason
    try:
        with _capture_lock:
            bp_id = bp_loc.GetBreakpoint().GetID()
            site_name = _bp_site[bp_id]
            _total_hits += 1
            _hit_counts[site_name] += 1
            report["candidate_sites"][site_name]["callback_records"] += 1
            regs = {name: register_value(frame, name)
                    for name in ("pc", "lr", "sp", "x0", "x1", "x2", "x3",
                                 "x4", "x5", "x6", "x7", "x29", "x30")}
            lr = regs.get("lr")
            caller_file_address = main_image_file_address(frame, lr)
            record = {
                "label": CAPTURE_LABEL,
                "site": site_name,
                "breakpoint_id": bp_id,
                "hit_index": _hit_counts[site_name],
                "total_hit_index": _total_hits,
                "thread_id": frame.GetThread().GetThreadID(),
                "caller_return_runtime": None if lr is None else hex(lr),
                "caller_return_unslid": (
                    None if caller_file_address is None
                    else hex(caller_file_address)
                ),
                "caller_return_unslid_resolution": (
                    "MH Unite module" if caller_file_address is not None
                    else "not resolved within MH Unite module"
                ),
                "registers": {name: (None if val is None else hex(val))
                              for name, val in regs.items()},
            }
            report["hits"].append(record)
            print('MHFU_RENDER_HIT=' + json.dumps(record, sort_keys=True), flush=True)

            if _hit_counts[site_name] >= MAX_HITS_PER_SITE:
                bp_loc.GetBreakpoint().SetEnabled(False)
                emit("site_hit_limit", site=site_name, count=_hit_counts[site_name])
            if _total_hits >= MAX_TOTAL_HITS:
                _stop_reason = "maximum total hit count reached"
                emit("total_hit_limit", count=_total_hits)
                return True
            return False
    except Exception as error:
        _callback_errors += 1
        site_name = _bp_site.get(bp_loc.GetBreakpoint().GetID(), "unknown")
        if site_name in report["candidate_sites"]:
            report["candidate_sites"][site_name]["callback_errors"] += 1
        trace = traceback.format_exc()
        emit("callback_exception", site=site_name, error=str(error), traceback=trace)
        print("MHFU_RENDER_TRACEBACK=" + trace, file=sys.stderr, flush=True)
        return False

def record_state(label, process):
    snapshot = state(process)
    emit("process_state", label=label, **snapshot)
    return snapshot

def wait_until_capture_stops(process, listener, broadcaster, mask):
    capture = wait_state(
        process,
        lldb.eStateStopped,
        CAPTURE_SECONDS,
        listener,
        broadcaster,
        mask,
        "capture",
    )
    if capture["reached"]:
        return {
            "stopped": True,
            "reason": capture["reason"],
            "transitions": capture["transitions"],
            "stop_request": None,
        }

    current = capture.get("state", state(process))
    if not current["valid"] or current["pid"] != EXPECTED_PID:
        return {
            "stopped": False,
            "reason": "capture ended without a valid handle for the target PID",
            "state": current,
            "transitions": capture["transitions"],
            "stop_request": None,
        }
    if current["state"] in (
        lldb.eStateExited, lldb.eStateCrashed, lldb.eStateDetached,
        lldb.eStateUnloaded, lldb.eStateInvalid,
    ):
        return {
            "stopped": False,
            "reason": "capture ended in a terminal process state",
            "state": current,
            "transitions": capture["transitions"],
            "stop_request": None,
        }

    # End the bounded capture window with one process Stop from this LLDB
    # control thread. Do not retry if Stop fails.
    emit("capture_window_stop_before", state=current, reason=capture["reason"])
    stop_error = process.Stop()
    stop_result = {
        "succeeded": bool(stop_error.Success()),
        "error": stop_error.GetCString() or "",
    }
    emit("capture_window_stop_after", **stop_result)
    if not stop_error.Success():
        current = state(process)
        return {
            "stopped": current["state"] == lldb.eStateStopped,
            "reason": "capture Stop failed; no retry attempted",
            "state": current,
            "transitions": capture["transitions"],
            "stop_request": stop_result,
        }
    stopped = wait_state(
        process,
        lldb.eStateStopped,
        STOP_TIMEOUT_SECONDS,
        listener,
        broadcaster,
        mask,
        "capture stop",
    )
    return {
        "stopped": stopped["reached"],
        "reason": stopped["reason"],
        "state": stopped["state"],
        "transitions": capture["transitions"] + stopped["transitions"],
        "stop_request": stop_result,
    }

def collect_site_counts(target, breakpoints):
    summary = {}
    for name, site in report["candidate_sites"].items():
        bp_id = site.get("breakpoint_id")
        bp = breakpoints.get(bp_id)
        try:
            bp_hits = int(bp.GetHitCount()) if bp and bp.IsValid() else None
        except Exception as error:
            bp_hits = None
            site["hit_count_error"] = str(error)
        callback_records = int(site.get("callback_records", 0))
        callback_errors = int(site.get("callback_errors", 0))
        if site.get("breakpoint_setup_status") != "installed":
            classification = "breakpoint_not_installed"
        elif bp_hits == 0:
            classification = "not_reached"
        elif bp_hits is None:
            classification = "breakpoint_hit_count_unavailable"
        elif callback_errors or callback_records < bp_hits:
            classification = "breakpoint_hit_but_callback_data_incomplete"
        else:
            classification = "reached_and_callback_data_collected"
        site.update({
            "breakpoint_hit_count": bp_hits,
            "callback_records": callback_records,
            "callback_errors": callback_errors,
            "classification": classification,
        })
        summary[name] = {
            "breakpoint_hit_count": bp_hits,
            "callback_records": callback_records,
            "callback_errors": callback_errors,
            "classification": classification,
        }
    return summary

def remove_breakpoints(target, breakpoints):
    results = []
    for bp_id, bp in list(breakpoints.items()):
        try:
            deleted = bool(target.BreakpointDelete(bp_id))
            remaining = target.FindBreakpointByID(bp_id)
            invalidated = not (remaining and remaining.IsValid())
            results.append({
                "breakpoint_id": bp_id,
                "delete_returned": deleted,
                "invalidated": invalidated,
            })
        except Exception as error:
            results.append({
                "breakpoint_id": bp_id,
                "delete_returned": False,
                "invalidated": False,
                "error": str(error),
                "traceback": traceback.format_exc(),
            })
        emit("breakpoint_cleanup", **results[-1])
    return results

def collect_final_counts(breakpoints):
    summary = report.get("candidate_sites", {})
    for name, site in summary.items():
        site["callback_records"] = int(_hit_counts.get(name, 0))
        site["callback_errors"] = int(site.get("callback_errors", 0))
        if site.get("breakpoint_setup_status") != "installed":
            site["classification"] = "breakpoint_not_installed"
        elif site.get("breakpoint_hit_count") is None:
            site["classification"] = "breakpoint hit count unavailable"
    return summary

def detach_after_cleanup(process):
    before = state(process)
    report["state_before_detach"] = before
    emit("detach_precondition", process_state=before,
         pid_matches_target=(before.get("pid") == EXPECTED_PID),
         handle_valid=before.get("valid") is True)
    if (not before["valid"] or before["pid"] != EXPECTED_PID
            or before["state"] != lldb.eStateStopped):
        report["detach_skipped_reason"] = (
            "detach requires the expected PID in eStateStopped"
        )
        return False

    listener, broadcaster, mask = listener_for(process, "mhfu-render-detach")
    try:
        report["detach_attempted"] = True
        emit("detach_before", api="SBProcess.Detach",
             process_state=before, pid=before["pid"])
        detach_error = process.Detach()
        report["detach"] = {
            "api": "SBProcess.Detach",
            "return_value_repr": repr(detach_error),
            "succeeded": bool(detach_error.Success()),
            "error": detach_error.GetCString() or "",
        }
        emit("detach_after", return_value_repr=repr(detach_error),
             sb_error_success=bool(detach_error.Success()),
             sb_error_message=detach_error.GetCString() or "")
        wait = wait_state(
            process, lldb.eStateDetached, DETACH_STATE_TIMEOUT_SECONDS,
            listener, broadcaster, mask, "detach"
        )
        report["detach_state_wait"] = wait
        report["detach_state_transitions"] = wait["transitions"]
        report["detached_state"] = wait["state"]
        report["detached_verified"] = (
            bool(detach_error.Success()) and wait["reached"]
        )
        emit("detach_state_wait_after", reached=wait["reached"],
             timed_out=wait.get("timed_out", False), state=wait["state"],
             transitions=wait["transitions"])
        return report["detached_verified"]
    except Exception as error:
        trace = traceback.format_exc()
        report["detach_exception"] = str(error)
        report["detach_traceback"] = trace
        emit("detach_exception", error=str(error), traceback=trace)
        print("MHFU_RENDER_TRACEBACK=" + trace, file=sys.stderr, flush=True)
        return False
    finally:
        remove_listener(listener, broadcaster, mask)

def main():
    global _stop_reason
    attach_listener = None
    attach_broadcaster = None
    attach_mask = None
    capture_listener = None
    capture_broadcaster = None
    capture_mask = None
    target = None
    process = None
    debugger_async_before = None
    confirmed_attached = False
    breakpoints = {}
    breakpoints_removed = False
    try:
        selection = command("device select " + DEVICE_ID)
        report["selection"] = selection
        if selection["return_status"] not in finish_statuses | {started_status}:
            raise RuntimeError("device selection returned an unexpected status")
        listing = command("device process list")
        report["device_process_list"] = {
            k: v for k, v in listing.items() if k != "output"
        }
        matches = [line.strip() for line in listing["output"].splitlines()
                   if line.split() and line.split()[0] == str(EXPECTED_PID)
                   and line.rstrip().endswith(EXECUTABLE_NAME)]
        report["selected_device_verified"] = (
            listing["return_status"] in finish_statuses
            and listing["succeeded"] and len(matches) == 1
