        report["attach"] = attach_result
        target = debugger.GetSelectedTarget()
        process = target.GetProcess() if target and target.IsValid() else None
        attach_snapshot = state(process)
        report["attached_process_state"] = attach_snapshot
        if not attach_snapshot["valid"] or attach_snapshot["pid"] != EXPECTED_PID:
            raise RuntimeError("attach did not yield the expected process handle")
        attach_listener, attach_broadcaster, attach_mask = listener_for(
            process, "mhfu-render-attach"
        )
        try:
            attach_wait = wait_state(
                process, lldb.eStateStopped, ATTACH_TIMEOUT_SECONDS, attach_listener,
                attach_broadcaster, attach_mask, "attach"
            )
        finally:
            remove_listener(attach_listener, attach_broadcaster, attach_mask)
