                or header_load == lldb.LLDB_INVALID_ADDRESS):
            raise RuntimeError("could not resolve executable header/ASLR slide")
        slide = header_load - header_file
        report["slide"] = hex(slide)
        report["slide_value"] = slide
        report["candidate_resolution"] = {}
        resolved = {}
        for name, unslid in UNSLID_SITES.items():
            try:
                file_address = module.ResolveFileAddress(unslid)
                if not file_address.IsValid():
                    raise RuntimeError("address did not resolve in MH Unite")
                load_address = file_address.GetLoadAddress(target)
                if (load_address == lldb.LLDB_INVALID_ADDRESS
                        or load_address - unslid != slide):
                    raise RuntimeError("resolved load address disagrees with slide")
                resolved[name] = load_address
                report["candidate_resolution"][name] = {
                    "unslid": hex(unslid),
                    "runtime": hex(load_address),
                    "slide": hex(slide),
                    "status": "resolved; user-facing identity still unverified",
                }
                report["candidate_sites"][name]["resolution_status"] = "resolved"
            except Exception as resolve_error:
                report["candidate_resolution"][name] = {
                    "unslid": hex(unslid),
                    "status": "unresolved",
                    "error": str(resolve_error),
                }
                report["candidate_sites"][name]["resolution_status"] = "unresolved"
                report["candidate_sites"][name]["breakpoint_setup_status"] = "not attempted"
                emit("candidate_resolution_failed", site=name,
                     unslid=hex(unslid), error=str(resolve_error))

        installed_sites = []
        for name, unslid in UNSLID_SITES.items():
            if name not in resolved:
                continue
            install_hardware_breakpoint(
                target, name, unslid, resolved[name], breakpoints
            )
            installed_sites.append(name)

        report["breakpoints_installed"] = len(installed_sites)
        if not installed_sites:
            raise RuntimeError("no candidate hardware breakpoints were installed")

        capture_listener, capture_broadcaster, capture_mask = listener_for(
            process, "mhfu-render-capture"
        )
        emit("capture_window_start", label=CAPTURE_LABEL,
             seconds=CAPTURE_SECONDS, max_total_hits=MAX_TOTAL_HITS)
        debugger_async_before = bool(debugger.GetAsync())
        debugger.SetAsync(True)
        report["debugger_async_before_capture"] = debugger_async_before
        report["capture_started_at"] = time.monotonic()
        continue_error = process.Continue()
        report["continue_error"] = {
            "succeeded": bool(continue_error.Success()),
            "message": continue_error.GetCString() or "",
        }
        emit("continue_returned",
             succeeded=bool(continue_error.Success()),
             message=continue_error.GetCString() or "",
             state=state(process))
        if not continue_error.Success():
            raise RuntimeError("process continue failed: " + (continue_error.GetCString() or ""))

        capture_wait = wait_until_capture_stops(
            process, capture_listener, capture_broadcaster, capture_mask
        )
        report["capture_wait"] = capture_wait
        report["capture_state_transitions"] = capture_wait["transitions"]
        if not capture_wait["stopped"]:
            report["cleanup_outcome"] = (
                "process was not confirmed stopped; breakpoints were not removed "
                "and detach was skipped"
            )
            raise RuntimeError(capture_wait["reason"])

        report["capture_stop_reason"] = _stop_reason or "capture window elapsed"
        report["candidate_sites"] = collect_site_counts(target, breakpoints)
        report["inspection"] = "capture complete"
    except Exception as error:
        report["status"] = "failed"
        report["failure"] = str(error)
        report["python_traceback"] = traceback.format_exc()
        emit("python_exception", error=str(error), traceback=report["python_traceback"])
        print("MHFU_RENDER_TRACEBACK=" + report["python_traceback"],
              file=sys.stderr, flush=True)
    finally:
        if confirmed_attached:
            state_before_cleanup = state(process)
            report["state_before_breakpoint_cleanup"] = state_before_cleanup
            if (state_before_cleanup["valid"]
                    and state_before_cleanup["pid"] == EXPECTED_PID
                    and state_before_cleanup["state"] == lldb.eStateStopped):
                report["candidate_sites"] = collect_site_counts(target, breakpoints)
                cleanup_ok = remove_breakpoints(target, breakpoints)
                report["breakpoint_cleanup"] = cleanup_ok
                breakpoints_removed = (
                    len(cleanup_ok) == len(breakpoints)
                    and all(item["deleted"] and item["invalidated"] for item in cleanup_ok)
                )
                report["breakpoints_removed_before_detach"] = breakpoints_removed
                if breakpoints_removed:
                    detach_after_cleanup(process)
                else:
                    report["detach_skipped_reason"] = (
                        "one or more temporary breakpoints were not confirmed removed"
                    )
            else:
                report["breakpoints_removed_before_detach"] = False
                report["detach_skipped_reason"] = (
                    "process was not confirmed stopped with the expected PID; "
                    "breakpoint cleanup and detach were skipped"
                )
        report["candidate_sites"] = collect_final_counts(breakpoints)
        if debugger_async_before is not None:
            try:
                debugger.SetAsync(debugger_async_before)
                report["debugger_async_restored"] = True
            except Exception as async_error:
                report["debugger_async_restored"] = False
                report["debugger_async_restore_error"] = str(async_error)
        if "status" not in report:
            if (report.get("inspection") == "capture complete"
                    and report.get("breakpoints_removed_before_detach")
                    and report.get("detached_verified")):
                report["status"] = (
                    "success: bounded rendering capture, breakpoint cleanup, "
                    "and detach verified"
                )
            else:
                report["status"] = (
                    "incomplete: see process state, hit counts, and cleanup fields"
                )
    print('MHFU_RENDER_RESULT=' + json.dumps(report, sort_keys=True, default=str), flush=True)

